LOCK TABLES `articles` WRITE;
/*!40000 ALTER TABLE `articles` DISABLE KEYS */;
INSERT INTO `articles` VALUES (1,1,'การตั้งค่า IP และ DNS บน Windows 11 สำหรับเครือข่ายสำนักงาน','เกริ่นนำ\nการกำหนดค่าหมายเลข IP Address และ DNS Server ที่ถูกต้องช่วยให้เครื่องคอมพิวเตอร์สามารถสื่อสารกับระบบเครือข่ายภายในหน่วยงานและออกสู่อินเทอร์เน็ตได้อย่างเสถียร หากไม่ได้รับการกำหนดหมายเลข IP เฉพาะจากเจ้าหน้าที่ ควรตั้งค่าเป็นแบบรับค่าอัตโนมัติ (DHCP) เพื่อป้องกันปัญหาหมายเลข IP ชนกันในระบบ\n\nข้อควรระวังก่อนดำเนินการ: หากเครื่องคอมพิวเตอร์ของคุณใช้เชื่อมต่อกับระบบเครื่องพิมพ์แม่ข่ายหรือระบบสารสนเทศเฉพาะทาง ควรจดบันทึกค่า IP และ DNS เดิมไว้ก่อนทำการเปลี่ยนแปลงทุกครั้ง เพื่อใช้เป็นข้อมูลอ้างอิงหากต้องติดต่อเจ้าหน้าที่ศูนย์ ICT ขอนแก่น','[\"กดปุ่ม Start แล้วเลือก Settings (รูปฟันเฟือง) จากนั้นคลิกเมนู Network & internet ทางด้านซ้าย\", \"เลือกประเภทการเชื่อมต่อที่ใช้งานอยู่ ได้แก่ Wi-Fi (เครือข่ายไร้สาย) หรือ Ethernet (สายสัญญาณ LAN)\", \"คลิกเข้าไปที่ชื่อเครือข่ายที่เชื่อมต่ออยู่ แล้วเลื่อนลงมาที่หัวข้อ IP assignment จากนั้นคลิกปุ่ม Edit\", \"เลือกโหมด Automatic (DHCP) สำหรับการใช้งานทั่วไป หรือเลือก Manual หากได้รับใบกำหนดค่า IP เฉพาะจากเจ้าหน้าที่\", \"ในหัวข้อ DNS server assignment ให้เลือก Automatic (DHCP) หรือระบุหมายเลข DNS ของหน่วยงาน แล้วกด Save\", \"เปิดโปรแกรมเบราว์เซอร์และทดลองเข้าเว็บไซต์ www.kkict.net เพื่อตรวจสอบว่าการเชื่อมต่อกลับมาใช้งานได้ปกติ\"]','[\"Windows\", \"Windows 11\", \"IP\", \"DNS\", \"เครือข่าย\", \"DHCP\", \"คอมพิวเตอร์\"]','/uploads/00000000-0000-4000-8000-000000000001.png','[\"/uploads/00000000-0000-4000-8000-000000000001.png\"]','/uploads/00000000-0000-4000-8000-000000000001.pdf',NULL,241,'PUBLISHED',1,'2026-11-08 08:44:11.255000','2026-11-24 08:44:11.261000','2026-11-24 08:44:11.261000'),(2,1,'แนวทางตรวจสอบและแก้ไขเมื่อคอมพิวเตอร์ทำงานช้าหรือค้างบ่อย','เกริ่นนำ\nอาการเครื่องคอมพิวเตอร์ตอบสนองช้า เปิดโปรแกรมใช้เวลานาน หรือค้างระหว่างปฏิบัติงาน มักเกิดจากการเปิดโปรแกรมพร้อมกันจำนวนมาก พื้นที่ไดรฟ์ระบบ (Drive C:) เหลือน้อยกว่าเกณฑ์มาตรฐาน หรือระบบปฏิบัติการกำลังดาวน์โหลดอัปเดตอยู่เบื้องหลัง\n\nการตรวจสอบทรัพยากรเครื่องเบื้องต้นด้วยตนเองจะช่วยแยกแยะได้ว่าเป็นปัญหาจากซอฟต์แวร์ที่แก้ไขได้ทันที หรือเป็นอาการเสื่อมสภาพของฮาร์ดแวร์ เช่น ฮาร์ดดิสก์และหน่วยความจำ (RAM) ที่ควรส่งให้เจ้าหน้าที่ตรวจสอบ','[\"บันทึกไฟล์เอกสารที่กำลังทำงานอยู่ทั้งหมด แล้วปิดโปรแกรมและแท็บเบราว์เซอร์ที่ไม่ได้ใช้งาน\", \"กดปุ่ม Ctrl + Shift + Esc เพื่อเปิดหน้าต่าง Task Manager แล้วดูที่แท็บ Processes ว่าโปรแกรมใดใช้ CPU, Memory หรือ Disk สูงผิดปกติ\", \"เปิด This PC เพื่อตรวจสอบพื้นที่ว่างของ Drive C: โดยควรมีพื้นที่ว่างอย่างน้อย 15–20 GB เพื่อให้ระบบทำงานได้ราบรื่น\", \"ใช้เครื่องมือ Disk Cleanup หรือ Storage Sense ของ Windows เพื่อลบเฉพาะไฟล์ชั่วคราว (Temporary files) และล้างถังขยะ Recycle Bin\", \"สั่ง Restart เครื่องคอมพิวเตอร์ 1 ครั้ง (เลือก Restart แทนการ Shut down) เพื่อล้างหน่วยความจำค้างของระบบ\", \"หากเครื่องยังค้างซ้ำหรือมีเสียงผิดปกติจากตัวเครื่อง ให้จดข้อความแจ้งเตือนและแจ้งเจ้าหน้าที่ศูนย์ ICT เข้าตรวจสอบ\"]','[\"คอมพิวเตอร์\", \"Windows\", \"เครื่องช้า\", \"เครื่องค้าง\", \"Task Manager\", \"RAM\", \"Disk\"]','/uploads/00000000-0000-4000-8000-000000000002.png','[\"/uploads/00000000-0000-4000-8000-000000000002.png\"]','/uploads/00000000-0000-4000-8000-000000000002.pdf',NULL,118,'PUBLISHED',0,'2026-10-27 08:44:11.358000','2026-11-24 08:44:11.360000','2026-11-24 08:44:11.360000'),(3,1,'การตรวจสอบเมื่อจอภาพไม่แสดงผล เมาส์หรือคีย์บอร์ดไม่ตอบสนอง','เกริ่นนำ\nเมื่อเปิดเครื่องคอมพิวเตอร์แล้วหน้าจอมืด ขึ้นข้อความ No Signal หรืออุปกรณ์ต่อพ่วงอย่างเมาส์และคีย์บอร์ดไม่สามารถใช้งานได้ สาเหตุส่วนใหญ่มักเกิดจากสายสัญญาณหลวม พอร์ตเชื่อมต่อจ่ายไฟไม่สมบูรณ์ หรือหน้าจอถูกสลับโหมดการแสดงผล\n\nก่อนแจ้งซ่อมฮาร์ดแวร์ แนะนำให้ตรวจสอบจุดเชื่อมต่อภายนอกตามขั้นตอนมาตรฐานด้านล่าง ซึ่งสามารถแก้ไขปัญหาเฉพาะหน้าได้มากกว่า 80% ของกรณีที่พบในสำนักงานและห้องอบรม','[\"สังเกตไฟสถานะที่ตัวเครื่องคอมพิวเตอร์ (Case) และไฟที่มุมจอภาพว่าติดสว่างอยู่หรือไม่ หากดับให้ตรวจปลั๊กไฟและเครื่องสำรองไฟ (UPS)\", \"ขยับและเสียบสายสัญญาณภาพ (HDMI, DisplayPort หรือ VGA) ทั้งฝั่งหลังจอภาพและหลังเครื่องคอมพิวเตอร์ให้แน่นสนิท\", \"กดปุ่ม Input / Source บนตัวจอภาพเพื่อตรวจสอบว่าจอเลือกช่องรับสัญญาณตรงกับสายที่เสียบใช้งานอยู่\", \"กรณีเมาส์หรือคีย์บอร์ดไม่ทำงาน ให้ถอดสาย USB ออกแล้วทดลองเสียบเปลี่ยนไปใช้พอร์ต USB ด้านหลังเครื่องโดยตรง\", \"หากเป็นเมาส์หรือคีย์บอร์ดไร้สาย ให้ตรวจสอบสวิตช์เปิด-ปิดใต้ตัวอุปกรณ์และเปลี่ยนแบตเตอรี่ก้อนใหม่\", \"กดปุ่ม Windows + Ctrl + Shift + B พร้อมกันเพื่อรีเซ็ตการแสดงผลของการ์ดจอ หากยังไม่ติดให้แจ้งเจ้าหน้าที่ตรวจสอบอุปกรณ์\"]','[\"จอภาพ\", \"เมาส์\", \"คีย์บอร์ด\", \"คอมพิวเตอร์\", \"No Signal\", \"USB\", \"อุปกรณ์\"]','/uploads/00000000-0000-4000-8000-000000000003.png','[\"/uploads/00000000-0000-4000-8000-000000000003.png\"]','/uploads/00000000-0000-4000-8000-000000000003.pdf',NULL,89,'PUBLISHED',0,'2026-10-11 08:44:11.442000','2026-11-24 08:44:11.443000','2026-11-24 08:44:11.443000'),(4,2,'แนวทางแก้ไขเมื่อเชื่อมต่อเครือข่ายไร้สาย (Wi-Fi) ไม่ได้','เกริ่นนำ\nเมื่อคอมพิวเตอร์โน้ตบุ๊ก แท็บเล็ต หรือสมาร์ตโฟนไม่สามารถเชื่อมต่อสัญญาณ Wi-Fi ของศูนย์หรือหน่วยงานได้ หรือเชื่อมต่อแล้วขึ้นสถานะไม่มีอินเทอร์เน็ต (No Internet, Secured) อาจเกิดจากการจำค่าเครือข่ายเดิมที่หมดอายุ สัญญาณอ่อน หรือโหมดประหยัดพลังงานของตัวรับสัญญาณ\n\nคู่มือนี้รวบรวมขั้นตอนการรีเซ็ตการเชื่อมต่อไร้สายอย่างปลอดภัย ซึ่งใช้ได้ทั้งผู้มาใช้บริการพื้นที่การเรียนรู้ของศูนย์พัฒนาทักษะและการเรียนรู้ ICT ขอนแก่น และบุคลากรภายในหน่วยงาน','[\"ตรวจสอบว่าเปิดใช้งาน Wi-Fi แล้ว และไม่ได้เปิดโหมดเครื่องบิน (Airplane Mode) ค้างไว้บนอุปกรณ์\", \"เลือกชื่อเครือข่าย (SSID) ของศูนย์หรือหน่วยงานที่ถูกต้อง และตรวจสอบความแรงของสัญญาณว่ามีอย่างน้อย 2–3 ขีด\", \"คลิกที่ชื่อเครือข่ายเดิมแล้วเลือกคำสั่ง “ลืมเครือข่ายนี้” (Forget This Network) เพื่อล้างค่ารหัสผ่านหรือใบรับรองที่ค้างอยู่\", \"ปิด Wi-Fi รอประมาณ 10 วินาที แล้วเปิดใหม่อีกครั้ง จากนั้นเลือกเชื่อมต่อและกรอกรหัสผ่านหรือบัญชีผู้ใช้งานให้ถูกต้อง\", \"หากเข้าเว็บไซต์แล้วยังไม่ขึ้นหน้าล็อกอิน (Captive Portal) ให้เปิดเบราว์เซอร์และพิมพ์ http://neverssl.com หรือเข้าหน้าเว็บทั่วไปเพื่อกระตุ้นหน้ายืนยันตัวตน\", \"หากยังเชื่อมต่อไม่ได้เฉพาะจุดที่นั่งอยู่ ให้แจ้งชื่อเครือข่ายและบริเวณที่ใช้งานแก่เจ้าหน้าที่ประจำศูนย์\"]','[\"Wi-Fi\", \"wifi\", \"เครือข่าย\", \"อินเทอร์เน็ต\", \"ไร้สาย\", \"เชื่อมต่อไม่ได้\"]','/uploads/00000000-0000-4000-8000-000000000004.png','[\"/uploads/00000000-0000-4000-8000-000000000004.png\"]','/uploads/00000000-0000-4000-8000-000000000004.pdf',NULL,286,'PUBLISHED',1,'2026-11-08 08:44:11.554000','2026-11-24 08:44:11.556000','2026-11-24 08:44:11.556000'),(5,2,'ตรวจสอบเมื่ออินเทอร์เน็ตใช้งานได้ช้าหรือสัญญาณขาดช่วง','เกริ่นนำ\nอาการเปิดหน้าเว็บช้า ดาวน์โหลดเอกสารไม่สำเร็จ หรือสัญญาณหลุดเป็นระยะ อาจมีสาเหตุได้ทั้งจากความหนาแน่นของผู้ใช้งานในจุดกระจายสัญญาณเดียวกัน การรบกวนของคลื่นความถี่ หรือมีโปรแกรมในเครื่องกำลังซิงก์ข้อมูลขนาดใหญ่\n\nการเปรียบเทียบอาการระหว่างเว็บไซต์ภายในกับภายนอก รวมถึงการทดสอบจากอุปกรณ์มากกว่าหนึ่งเครื่อง จะช่วยให้เจ้าหน้าที่วิเคราะห์จุดเกิดเหตุและแก้ไขได้อย่างแม่นยำ','[\"ทดลองเปิดเว็บไซต์ของศูนย์ (https://www.kkict.net/) เปรียบเทียบกับเว็บไซต์ภายนอก เพื่อดูว่าเป็นปัญหาเฉพาะบางเว็บหรือทั้งระบบ\", \"ขยับอุปกรณ์เข้าใกล้จุดกระจายสัญญาณ (Access Point) และหลีกเลี่ยงการวางอุปกรณ์หลังสิ่งกีดขวางที่เป็นโลหะหรือผนังหนา\", \"หากอุปกรณ์รองรับคลื่นความถี่ 5 GHz ให้เลือกเชื่อมต่อชื่อเครือข่ายที่เป็น 5 GHz เพื่อลดสัญญาณรบกวนและได้ความเร็วที่เสถียรกว่า\", \"หยุดการดาวน์โหลดไฟล์ขนาดใหญ่ การอัปโหลดวิดีโอ หรือการซิงก์คลาวด์ชั่วคราวในขณะประชุมหรือใช้งานระบบสำคัญ\", \"ทดสอบความเร็วและการตอบสนองจากอุปกรณ์อีกเครื่องในบริเวณเดียวกัน เพื่อแยกแยะปัญหาของตัวเครื่องออกจากระบบเครือข่าย\", \"แจ้งช่วงเวลาที่พบอาการและหมายเลขห้องหรือโซนที่ใช้งานแก่เจ้าหน้าที่ศูนย์ ICT เพื่อตรวจสอบปริมาณทราฟฟิก\"]','[\"อินเทอร์เน็ต\", \"Wi-Fi\", \"wifi\", \"เครือข่าย\", \"เน็ตช้า\", \"5GHz\"]','/uploads/00000000-0000-4000-8000-000000000005.png','[\"/uploads/00000000-0000-4000-8000-000000000005.png\"]','/uploads/00000000-0000-4000-8000-000000000005.pdf',NULL,152,'PUBLISHED',0,'2026-11-07 08:44:11.643000','2026-11-24 08:44:11.644000','2026-11-24 08:44:11.644000'),(6,2,'การเชื่อมต่อเครือข่ายเสมือน (VPN) และการเข้าใช้ระบบภายในจากภายนอก','เกริ่นนำ\nสำหรับการปฏิบัติงานนอกสถานที่หรือการเข้าถึงฐานข้อมูลและระบบสารบรรณภายในหน่วยงาน จำเป็นต้องเชื่อมต่อผ่านระบบเครือข่ายส่วนตัวเสมือน (VPN) ที่ได้รับการเข้ารหัสเพื่อรักษาความมั่นคงปลอดภัยของข้อมูลราชการ\n\nผู้ใช้งานต้องได้รับอนุมัติสิทธิ์บัญชี VPN จากหน่วยงานก่อนเริ่มตั้งค่า และห้ามใช้งานผ่านเครื่องคอมพิวเตอร์สาธารณะที่ไม่มีระบบป้องกันไวรัสโดยเด็ดขาด','[\"ตรวจสอบว่าอุปกรณ์เชื่อมต่ออินเทอร์เน็ตที่เสถียรแล้ว (แนะนำให้ใช้เครือข่ายบ้านหรือฮอตสปอตส่วนตัวแทน Wi-Fi สาธารณะ)\", \"เปิดโปรแกรม VPN Client ที่หน่วยงานกำหนด หรือไปที่ Settings > Network & internet > VPN บนระบบปฏิบัติการ Windows\", \"ตรวจสอบชื่อเซิร์ฟเวอร์ปลายทาง (Server address) และประเภทโปรโตคอลตามเอกสารใบแจ้งสิทธิ์ที่ได้รับจากศูนย์ ICT\", \"กรอกชื่อผู้ใช้ (Username) และรหัสผ่าน พร้อมรหัสยืนยันตัวตนสองชั้น (OTP) หากระบบมีการร้องขอ แล้วกด Connect\", \"เมื่อสถานะขึ้น Connected แล้ว จึงเปิดเบราว์เซอร์เพื่อเข้าใช้งานระบบภายในของหน่วยงานตามปกติ\", \"เมื่อสิ้นสุดการปฏิบัติงานทุกครั้ง ให้กด Disconnect ออกจากระบบ VPN ทันทีเพื่อความปลอดภัยของบัญชีและเครือข่าย\"]','[\"VPN\", \"vpn\", \"เครือข่าย\", \"ทำงานจากบ้าน\", \"ระบบภายใน\", \"ความปลอดภัย\", \"อินเทอร์เน็ต\"]','/uploads/00000000-0000-4000-8000-000000000006.png','[\"/uploads/00000000-0000-4000-8000-000000000006.png\"]','/uploads/00000000-0000-4000-8000-000000000006.pdf',NULL,134,'PUBLISHED',0,'2026-10-11 08:44:11.720000','2026-11-24 08:44:11.722000','2026-11-24 08:44:11.722000'),(7,3,'การบันทึกเอกสารราชการ การแปลงไฟล์ PDF และการกู้คืนไฟล์ฉบับก่อนหน้า','เกริ่นนำ\nการจัดเก็บไฟล์เอกสารอย่างเป็นระบบและการตั้งค่าการบันทึกอัตโนมัติ (AutoRecover) ช่วยป้องกันการสูญหายของข้อมูลเมื่อเกิดไฟดับหรือโปรแกรมปิดตัวเองกะทันหัน รวมถึงการส่งออกเป็นไฟล์ PDF มาตรฐานช่วยให้แบบอักษรไทยไม่เพี้ยนเมื่อเปิดในเครื่องอื่น\n\nสำหรับการจัดทำหนังสือราชการหรือเอกสารเผยแพร่ แนะนำให้ใช้ฟอนต์มาตรฐานราชการไทย (เช่น TH Sarabun PSK หรือ Sarabun) และตรวจสอบการฝังฟอนต์ก่อนส่งออกไฟล์ทุกครั้ง','[\"เลือกเมนู File > Save As แล้วเลือกโฟลเดอร์จัดเก็บงานที่กำหนด โดยตั้งชื่อไฟล์ระบุหัวข้อและวันที่ (เช่น รายงานสรุป_2569-11-06)\", \"ระหว่างพิมพ์งาน ให้กดปุ่มลัด Ctrl + S เป็นระยะ และเปิดใช้งานตั้งค่า Save AutoRecover information ทุก 5–10 นาที\", \"เมื่อต้องการส่งต่อเอกสารที่ไม่ต้องการให้รูปแบบเพี้ยน ให้เลือก File > Export > Create PDF/XPS Document\", \"กรณีโปรแกรมปิดกะทันหัน ให้เปิดโปรแกรมขึ้นมาใหม่ แล้วดูแถบ Document Recovery ด้านซ้ายเพื่อเลือกกู้คืนฉบับล่าสุด\", \"หากเผลอบันทึกทับไฟล์เดิม ให้คลิกขวาที่ไฟล์ เลือก Properties > Previous Versions หรือดูใน Version History ของระบบคลาวด์\", \"หลีกเลี่ยงการเปิดไฟล์เอกสารแนบที่มีนามสกุลแปลกปลอม (.exe, .scr, .vbs) หรือไฟล์ที่ขอให้กด Enable Macros จากแหล่งที่ไม่รู้จัก\"]','[\"โปรแกรม\", \"เอกสาร\", \"บันทึกไฟล์\", \"สำนักงาน\", \"PDF\", \"Word\", \"Excel\", \"กู้คืนไฟล์\"]','/uploads/00000000-0000-4000-8000-000000000007.png','[\"/uploads/00000000-0000-4000-8000-000000000007.png\"]','/uploads/00000000-0000-4000-8000-000000000007.pdf',NULL,96,'PUBLISHED',0,'2026-11-18 08:44:11.799000','2026-11-24 08:44:11.800000','2026-11-24 08:44:11.800000'),(8,3,'การเตรียมอุปกรณ์และแก้ไขปัญหาเสียง/กล้องในการประชุมออนไลน์','เกริ่นนำ\nการประชุมทางไกลหรือการเข้าอบรมออนไลน์ผ่านโปรแกรม Zoom, Microsoft Teams และ Google Meet มักพบปัญหาผู้เข้าร่วมไม่ได้ยินเสียง ไมโครโฟนไม่ดัง หรือกล้องเว็บแคมไม่แสดงภาพ ซึ่งส่วนใหญ่เกิดจากการเลือกอุปกรณ์รับ-ส่งสัญญาณ (Audio/Video Input) ไม่ตรงกับตัวที่เสียบใช้งาน\n\nควรเข้าห้องประชุมล่วงหน้าอย่างน้อย 10–15 นาทีเพื่อทดสอบระบบภาพและเสียง โดยเฉพาะเมื่อมีการต่อออกจอโปรเจกเตอร์หรือชุดเครื่องเสียงห้องประชุม','[\"เสียบชุดหูฟัง ไมโครโฟน หรือกล้องเว็บแคมเข้ากับพอร์ต USB ให้เรียบร้อยก่อนเปิดโปรแกรมประชุมออนไลน์\", \"ในหน้าต่างโปรแกรมประชุม ให้คลิกไอคอนลูกศรข้างปุ่มไมโครโฟน (Mute/Unmute) แล้วเลือกชื่อ Microphone และ Speaker ให้ตรงกับอุปกรณ์จริง\", \"ใช้คำสั่ง Test Speaker & Microphone ของโปรแกรมเพื่อทดลองฟังเสียงทดสอบและพูดใส่ไมโครโฟนดูแถบระดับเสียง\", \"หากกล้องไม่แสดงภาพ ให้ตรวจสอบฝาปิดหน้าเลนส์ (Privacy Shutter) และตรวจใน Windows Settings > Privacy & security > Camera ว่าเปิดอนุญาตแล้ว\", \"กรณีต้องการแชร์หน้าจอพร้อมเสียงวิดีโอ ให้ติ๊กถูกที่ช่อง Share sound / Include computer sound ก่อนกดยืนยันการแชร์\", \"ปิดไมโครโฟนทุกครั้งเมื่อไม่ได้เป็นผู้พูด เพื่อป้องกันเสียงสะท้อน (Echo) และเสียงรบกวนในห้องประชุม\"]','[\"ประชุมออนไลน์\", \"Zoom\", \"Teams\", \"Google Meet\", \"ไมโครโฟน\", \"กล้อง\", \"ซอฟต์แวร์\"]','/uploads/00000000-0000-4000-8000-000000000008.png','[\"/uploads/00000000-0000-4000-8000-000000000008.png\"]','/uploads/00000000-0000-4000-8000-000000000008.pdf',NULL,145,'PUBLISHED',0,'2026-11-14 08:44:11.871000','2026-11-24 08:44:11.872000','2026-11-24 08:44:11.872000'),(9,3,'แนวทางการสำรองข้อมูลไฟล์งานสำคัญตามหลัก 3-2-1 Backup','เกริ่นนำ\nข้อมูลเอกสารและฐานข้อมูลในการปฏิบัติงานอาจสูญหายได้จากทั้งอุปกรณ์ชำรุด การเผลอลบไฟล์ หรือภัยคุกคามทางไซเบอร์ การสำรองข้อมูลอย่างสม่ำเสมอตามหลัก 3-2-1 จึงเป็นมาตรการสำคัญที่สุดในการลดความเสียหายและช่วยให้ทำงานต่อเนื่องได้ทันที\n\nหลัก 3-2-1 ประกอบด้วย การมีข้อมูลอย่างน้อย 3 ชุด เก็บไว้ในสื่อบันทึกข้อมูล 2 ประเภทที่ต่างกัน และมี 1 ชุดที่เก็บแยกไว้คนละสถานที่หรือบนระบบคลาวด์ที่ได้รับอนุญาต','[\"คัดแยกโฟลเดอร์งานสำคัญที่ต้องสำรองข้อมูลเป็นประจำทุกสัปดาห์ โดยแยกออกจากไฟล์ดาวน์โหลดทั่วไป\", \"ตั้งชื่อโฟลเดอร์สำรองข้อมูลตามปีและเดือน (เช่น Backup_2569_11) เพื่อให้ง่ายต่อการค้นหาและตรวจสอบย้อนหลัง\", \"คัดลอกข้อมูลชุดสำรองลงในอุปกรณ์จัดเก็บภายนอก (External Hard Drive / Flash Drive สำหรับงานราชการ) หรือพื้นที่เครือข่ายส่วนกลาง\", \"หลังจากสำรองข้อมูลลงอุปกรณ์ภายนอกเสร็จแล้ว ให้ถอดการเชื่อมต่อ (Safely Remove Hardware) ทันที เพื่อป้องกันไวรัสเรียกค่าไถ่เข้ารหัสไฟล์สำรอง\", \"ทดลองสุ่มเปิดไฟล์จากชุดข้อมูลสำรองอย่างน้อยเดือนละ 1 ครั้ง เพื่อยืนยันว่าไฟล์สมบูรณ์และสามารถเปิดใช้งานได้จริง\"]','[\"สำรองข้อมูล\", \"Backup\", \"ไฟล์งาน\", \"ความปลอดภัย\", \"โปรแกรม\", \"เอกสาร\"]','/uploads/00000000-0000-4000-8000-000000000009.png','[\"/uploads/00000000-0000-4000-8000-000000000009.png\"]','/uploads/00000000-0000-4000-8000-000000000009.pdf',NULL,82,'PUBLISHED',0,'2026-10-18 08:44:11.946000','2026-11-24 08:44:11.947000','2026-11-24 08:44:11.947000'),(10,3,'ฉบับร่าง: คู่มือการใช้ซอฟต์แวร์ออกแบบ 3 มิติเบื้องต้นสำหรับห้อง Maker Space','เกริ่นนำ\nคู่มือฉบับร่างสำหรับผู้เข้าอบรมและประชาชนที่มาใช้บริการห้อง DIY / Maker Space ณ ศูนย์พัฒนาทักษะและการเรียนรู้ ICT เทศบาลนครขอนแก่น เพื่อเตรียมไฟล์โมเดล 3 มิติ (.STL) ก่อนส่งพิมพ์\n\nเอกสารนี้อยู่ระหว่างการตรวจทานภาพประกอบหน้าจอโปรแกรม Slicer โดยวิทยากรประจำศูนย์ก่อนเผยแพร่สู่สาธารณะ','[\"ตรวจสอบขนาดชิ้นงานในโปรแกรมออกแบบให้มีหน่วยเป็นมิลลิเมตร (mm) และไม่เกินขนาดฐานพิมพ์ของเครื่อง\", \"ส่งออกไฟล์ชิ้นงานเป็นนามสกุล .STL หรือ .OBJ ด้วยความละเอียดที่เหมาะสม\", \"นำไฟล์เข้าโปรแกรม Slicer เพื่อกำหนดความหนาชั้นเลเยอร์ (Layer Height) และโครงสร้างค้ำยัน (Support)\"]','[\"3D Printer\", \"Maker Space\", \"ซอฟต์แวร์\", \"ออกแบบ 3 มิติ\"]','/uploads/00000000-0000-4000-8000-000000000010.png','[\"/uploads/00000000-0000-4000-8000-000000000010.png\"]',NULL,NULL,0,'DRAFT',0,NULL,'2026-11-24 08:44:12.026000','2026-11-24 08:44:12.026000'),(11,4,'แก้ปัญหาสั่งพิมพ์งานผ่านเครื่องพิมพ์เครือข่าย (Network Printer) ไม่ออก','เกริ่นนำ\nเมื่อสั่งพิมพ์เอกสารผ่านเครื่องพิมพ์ส่วนกลางของสำนักงานแล้วไม่มีกระดาษออก หรือสถานะเครื่องพิมพ์ขึ้น Offline สาเหตุหลักมักเกิดจากคิวงานพิมพ์ก่อนหน้าค้าง เครื่องพิมพ์หลุดจากวงเครือข่าย หรือเลือกชื่อเครื่องพิมพ์ปลายทางผิดเครื่อง\n\nกรุณาหลีกเลี่ยงการกดสั่งพิมพ์ซ้ำหลายครั้งติดต่อกันเมื่อเอกสารยังไม่ออก เพราะจะทำให้คิวงานสะสมค้างและพิมพ์ออกมาซ้ำจำนวนมากเมื่อเครื่องกลับมาออนไลน์','[\"เดินไปตรวจสอบที่ตัวเครื่องพิมพ์ว่าเปิดสวิตช์อยู่ มีกระดาษในถาดเพียงพอ และไม่มีไฟกะพริบแจ้งเตือนกระดาษติด (Paper Jam)\", \"ตรวจสอบว่าคอมพิวเตอร์ของคุณเชื่อมต่ออยู่ในเครือข่ายเดียวกับเครื่องพิมพ์สำนักงาน\", \"เปิดหน้าต่าง Settings > Bluetooth & devices > Printers & scanners แล้วคลิกเลือกเครื่องพิมพ์ที่ใช้งาน จากนั้นกด Open print queue\", \"หากมีรายการเอกสารที่ขึ้นสถานะ Error หรือค้างอยู่นาน ให้คลิกขวาที่รายการนั้นแล้วเลือก Cancel เพื่อล้างคิวงานที่ค้าง\", \"ตรวจสอบในหน้าต่างสั่งพิมพ์ของโปรแกรมว่าเลือกชื่อ Network Printer ถูกต้อง และตั้งค่าขนาดกระดาษเป็น A4 ตรงกับถาดกระดาษ\", \"ทดลองสั่งพิมพ์เฉพาะหน้าแรก 1 หน้า (Print Current Page) หากยังขึ้น Offline ให้แจ้งชื่อรุ่นเครื่องพิมพ์แก่เจ้าหน้าที่ศูนย์ ICT\"]','[\"Printer\", \"printer\", \"เครื่องพิมพ์\", \"Network Printer\", \"พิมพ์ไม่ออก\", \"Offline\"]','/uploads/00000000-0000-4000-8000-000000000011.png','[\"/uploads/00000000-0000-4000-8000-000000000011.png\"]','/uploads/00000000-0000-4000-8000-000000000011.pdf',NULL,207,'PUBLISHED',1,'2026-10-28 08:44:12.028000','2026-11-24 08:44:12.029000','2026-11-24 08:44:12.029000'),(12,4,'การเปลี่ยนตลับหมึก การแก้ไขกระดาษติด และการดูแลคุณภาพงานพิมพ์','เกริ่นนำ\nเมื่อเอกสารที่พิมพ์ออกมามีสีซีดจาง มีแถบขาวขาดหาย หรือมีคราบหมึกเปื้อนบนกระดาษ มักเกิดจากผงหมึกหรือน้ำหมึกใกล้หมด หัวพิมพ์อุดตัน หรือลูกยางดึงกระดาษมีฝุ่นสะสม การดูแลรักษาตามขั้นตอนที่ถูกต้องช่วยยืดอายุการใช้งานของเครื่องพิมพ์ได้มาก\n\nข้อควรระวังด้านความปลอดภัย: สำหรับเครื่องพิมพ์เลเซอร์ ชุดทำความร้อน (Fuser Unit) ภายในเครื่องจะมีอุณหภูมิสูงมากหลังพิมพ์งาน ควรรอให้เครื่องเย็นลงก่อนเปิดฝาดึงกระดาษที่ติดออก','[\"ตรวจสอบระดับหมึกคงเหลือจากหน้าจอแสดงผลบนตัวเครื่องพิมพ์ หรือผ่านโปรแกรมสถานะเครื่องพิมพ์ในคอมพิวเตอร์\", \"หากกระดาษติด ให้ปิดเครื่องพิมพ์ เปิดฝาครอบตามคู่มือรุ่นนั้นๆ แล้วใช้สองมือค่อยๆ ดึงกระดาษออกตามทิศทางการเดินกระดาษอย่างช้าๆ เพื่อไม่ให้กระดาษฉีกขาดค้างด้านใน\", \"ก่อนใส่กระดาษปึกใหม่ลงถาด ให้กรีดกระดาษพอประมาณเพื่อลดไฟฟ้าสถิต และจัดฉากกั้นกระดาษให้พอดีกับขอบ A4\", \"กรณีเครื่องพิมพ์อิงก์เจ็ตพิมพ์เส้นขาดหรือสีเพี้ยน ให้สั่งคำสั่งทำความสะอาดหัวพิมพ์ (Print Head Cleaning) จากเมนู Maintenance ของเครื่อง\", \"เมื่อเปลี่ยนตลับหมึกใหม่ ให้ใช้ตลับหมึกที่ตรงรุ่นเท่านั้น และนำตลับหมึกเก่าส่งคืนจุดรวบรวมขยะอิเล็กทรอนิกส์ของหน่วยงาน\"]','[\"Printer\", \"หมึก\", \"เครื่องพิมพ์\", \"กระดาษติด\", \"ทำความสะอาดหัวพิมพ์\"]','/uploads/00000000-0000-4000-8000-000000000012.png','[\"/uploads/00000000-0000-4000-8000-000000000012.png\"]','/uploads/00000000-0000-4000-8000-000000000012.pdf',NULL,73,'PUBLISHED',0,'2026-10-27 08:44:12.106000','2026-11-24 08:44:12.107000','2026-11-24 08:44:12.107000'),(13,4,'วิธีการสแกนเอกสารเป็นไฟล์ PDF เพื่อแนบในระบบงานอิเล็กทรอนิกส์','เกริ่นนำ\nการจัดเก็บเอกสารกระดาษให้อยู่ในรูปแบบไฟล์ดิจิทัล (PDF) ที่มีความคมชัดและมีขนาดไฟล์ไม่ใหญ่เกินกำหนด เป็นขั้นตอนสำคัญสำหรับการรับ-ส่งหนังสือราชการและการจัดเก็บเอกสารอ้างอิงในคลังความรู้\n\nค่าความละเอียดมาตรฐานที่แนะนำสำหรับเอกสารตัวอักษรขาว-ดำหรือสีทั่วไปคือ 200 ถึง 300 DPI ซึ่งให้อักษรคมชัดอ่านง่ายและได้ขนาดไฟล์กะทัดรัดอัปโหลดได้รวดเร็ว','[\"ตรวจสอบเอกสารต้นฉบับ ถอดลวดเย็บกระดาษและคลิปหนีบออกทั้งหมดก่อนวางลงบนกระจกสแกนหรือถาดป้อนกระดาษอัตโนมัติ (ADF)\", \"วางเอกสารให้ชิดมุมลูกศรบอกตำแหน่งของเครื่องสแกน แล้วปิดฝาครอบลงให้สนิท\", \"เปิดโปรแกรมสแกนในคอมพิวเตอร์ หรือเลือกเมนู Scan to PC / Scan to PDF บนหน้าจอเครื่องมัลติฟังก์ชัน\", \"กำหนดรูปแบบไฟล์เป็น PDF, ขนาดกระดาษเป็น A4 และตั้งค่าความละเอียด (Resolution) ที่ 200 หรือ 300 DPI\", \"กดปุ่ม Preview (หากต้องการตรวจกรอบภาพ) แล้วกด Scan จากนั้นรวมหน้าเอกสารหลายแผ่นเข้าเป็นไฟล์ PDF เดียวกัน\", \"เปิดไฟล์ PDF ที่ได้เพื่อตรวจสอบความครบถ้วนของทุกหน้าและความถูกต้องของทิศทางหน้ากระดาษก่อนนำไปใช้งาน\"]','[\"สแกน\", \"Scanner\", \"PDF\", \"เครื่องพิมพ์\", \"เอกสาร\", \"e-Office\"]','/uploads/00000000-0000-4000-8000-000000000013.png','[\"/uploads/00000000-0000-4000-8000-000000000013.png\"]','/uploads/00000000-0000-4000-8000-000000000013.pdf',NULL,112,'PUBLISHED',0,'2026-11-02 08:44:12.233000','2026-11-24 08:44:12.234000','2026-11-24 08:44:12.234000'),(14,4,'ข้อปฏิบัติในการเข้าใช้งานอุปกรณ์ห้อง Maker Space (3D Printer และ CNC Laser)','เกริ่นนำ\nศูนย์พัฒนาทักษะและการเรียนรู้ ICT เทศบาลนครขอนแก่น มีบริการพื้นที่ปฏิบัติการ Maker Space / ห้อง DIY ซึ่งประกอบด้วยเครื่องพิมพ์ 3 มิติ (3D Printer), เครื่องแกะสลักและตัดด้วยเลเซอร์ (CNC Laser), เครื่อง 3D Scanner และอุปกรณ์ VR สำหรับส่งเสริมทักษะนวัตกรรมแก่เยาวชนและประชาชน\n\nเนื่องจากอุปกรณ์ในห้องปฏิบัติการมีความร้อนสูงและมีชิ้นส่วนกลไกที่เคลื่อนที่ด้วยความละเอียด ผู้เข้าใช้งานทุกท่านต้องปฏิบัติตามระเบียบความปลอดภัยและคำแนะนำของเจ้าหน้าที่ประจำศูนย์อย่างเคร่งครัด','[\"ลงทะเบียนเข้าใช้งานพื้นที่และแจ้งประเภทเครื่องมือที่ต้องการใช้บริการกับเจ้าหน้าที่ประจำศูนย์ ICT ขอนแก่นล่วงหน้า\", \"นำไฟล์งานให้เจ้าหน้าที่ตรวจสอบความถูกต้องของขนาด วัสดุ และเวลาที่ใช้ในการเดินเครื่องก่อนเริ่มสั่งงานทุกครั้ง\", \"สวมแว่นตานิรภัยและอุปกรณ์ป้องกันตามที่ศูนย์กำหนดเมื่อปฏิบัติงานใกล้เครื่อง CNC Laser หรือเครื่องมือช่าง\", \"ห้ามสัมผัสหัวฉีดพลาสติก (Nozzle) และฐานทำความร้อนของเครื่อง 3D Printer ขณะเครื่องกำลังทำงานหรือเพิ่งพิมพ์เสร็จใหม่ๆ\", \"เฝ้าสังเกตการทำงานช่วงเริ่มต้น (First Layer) จนชิ้นงานยึดเกาะฐานพิมพ์สมบูรณ์ หากพบความผิดปกติให้แจ้งเจ้าหน้าที่กดหยุดเครื่องทันที\", \"ทำความสะอาดพื้นที่ปฏิบัติงานและเก็บเครื่องมือเข้าที่เดิมหลังเสร็จสิ้นการใช้งานทุกครั้ง\"]','[\"3D Printer\", \"CNC Laser\", \"Maker Space\", \"DIY\", \"VR\", \"ศูนย์ ICT ขอนแก่น\", \"อุปกรณ์\"]','/uploads/00000000-0000-4000-8000-000000000014.png','[\"/uploads/00000000-0000-4000-8000-000000000014.png\"]','/uploads/00000000-0000-4000-8000-000000000014.pdf',NULL,168,'PUBLISHED',1,'2026-10-22 08:44:12.289000','2026-11-24 08:44:12.289000','2026-11-24 08:44:12.289000'),(15,5,'การเข้าใช้บริการศูนย์พัฒนาทักษะและการเรียนรู้ ICT เทศบาลนครขอนแก่น (kkict.net)','เกริ่นนำ\nศูนย์พัฒนาทักษะและการเรียนรู้ ICT เทศบาลนครขอนแก่น (KKICT) ตั้งอยู่ ณ ชั้น 2 ตลาดสดเทศบาล 1 ถนนกลางเมือง อำเภอเมืองขอนแก่น เปิดให้บริการพื้นที่การเรียนรู้ ห้องสมุดดิจิทัล บริการคอมพิวเตอร์และอินเทอร์เน็ต ห้องฝึกอบรมทักษะไอที และห้องปฏิบัติการ Maker Space สำหรับนักเรียน นักศึกษา บุคลากร และประชาชนทั่วไป\n\nผู้สนใจสามารถติดตามข่าวสาร ตารางหลักสูตรฝึกอบรมคอมพิวเตอร์และดิจิทัลที่เปิดรับสมัคร รวมถึงติดต่อสอบถามบริการต่างๆ ได้ผ่านทางเว็บไซต์ทางการ https://www.kkict.net/ หรือโทรศัพท์ 084-583-0208 ในเวลาทำการ','[\"เข้าสู่เว็บไซต์หลักของศูนย์ที่ https://www.kkict.net/ เพื่อตรวจสอบตารางกิจกรรม ข่าวประชาสัมพันธ์ และหลักสูตรอบรมที่เปิดรับสมัคร\", \"กรณีเดินทางมาใช้บริการที่ศูนย์ (ชั้น 2 ตลาดสดเทศบาล 1 ถนนกลางเมือง) ให้ติดต่อลงทะเบียนผู้เข้าใช้บริการที่เคาน์เตอร์ประชาสัมพันธ์\", \"แสดงบัตรประจำตัวประชาชนหรือบัตรนักเรียน/นักศึกษา เพื่อรับสิทธิ์เข้าใช้งานโซนคอมพิวเตอร์ ห้องสมุด หรือพื้นที่การเรียนรู้\", \"ปฏิบัติตามระเบียบการใช้พื้นที่ส่วนรวม ไม่นำอาหารและเครื่องดื่มเข้ามารับประทานบริเวณโต๊ะอุปกรณ์คอมพิวเตอร์\", \"เมื่อต้องการคำแนะนำในการใช้งานซอฟต์แวร์หรือพบปัญหาอุปกรณ์ขัดข้อง สามารถค้นหาจากคลังความรู้นี้หรือแจ้งเจ้าหน้าที่ประจำศูนย์ได้ทันที\"]','[\"kkict\", \"kkict.net\", \"ศูนย์ ICT ขอนแก่น\", \"อบรมคอมพิวเตอร์\", \"เทศบาลนครขอนแก่น\", \"บริการออนไลน์\"]','/uploads/00000000-0000-4000-8000-000000000015.png','[\"/uploads/00000000-0000-4000-8000-000000000015.png\"]','/uploads/00000000-0000-4000-8000-000000000015.pdf',NULL,295,'PUBLISHED',1,'2026-10-30 08:44:12.347000','2026-11-24 08:44:12.348000','2026-11-24 08:44:12.348000'),(16,5,'แนวทางตรวจสอบและแก้ไขเมื่อเข้าใช้ระบบสารสนเทศไม่ได้','เกริ่นนำ\nเมื่อไม่สามารถเข้าสู่ระบบสารสนเทศหรือเว็บแอปพลิเคชันของหน่วยงานได้ เช่น หน้าเว็บไม่โหลด ขึ้นแจ้งเตือนใบรับรองความปลอดภัย หรือกดเข้าสู่ระบบแล้วเด้งกลับหน้าเดิม อาจเกิดจากแคช (Cache) ของเบราว์เซอร์ค้าง วันเวลาในเครื่องไม่ตรงกับเวลาจริง หรือใช้เบราว์เซอร์รุ่นเก่า\n\nโปรดระมัดระวังไม่กรอกรหัสผ่านของระบบงานราชการลงในลิงก์ที่ส่งมาจากข้อความไม่ระบุตัวตน และควรเข้าผ่านบุ๊กมาร์กหรือหน้าเว็บไซต์หลักของหน่วยงานเสมอ','[\"ตรวจสอบการเชื่อมต่ออินเทอร์เน็ต และดูมุมขวาล่างของหน้าจอคอมพิวเตอร์ว่าวันที่และเวลา (Date & Time) ตรงกับเวลาปัจจุบันหรือไม่\", \"ตรวจสอบที่อยู่เว็บไซต์ (URL) บนแถบด้านบนของเบราว์เซอร์ว่าสะกดถูกต้องและขึ้นต้นด้วย https://\", \"ทดลองเปิดหน้าต่างไม่ระบุตัวตน (Incognito / InPrivate Window ด้วยปุ่ม Ctrl + Shift + N) แล้วเข้าสู่ระบบอีกครั้งเพื่อตัดปัญหาแคชค้าง\", \"หากเข้าผ่านโหมดไม่ระบุตัวตนได้ปกติ ให้ล้างข้อมูลแคชและคุกกี้ (Clear browsing data) ของเบราว์เซอร์หลัก\", \"ตรวจสอบภาษาของแป้นพิมพ์ (TH/EN) และปุ่ม Caps Lock ก่อนพิมพ์ชื่อผู้ใช้และรหัสผ่านด้วยตนเอง\", \"หากระบบแสดงข้อความผิดพลาด ให้บันทึกภาพหน้าจอ (โดยปกปิดรหัสผ่านและข้อมูลส่วนบุคคล) ส่งให้เจ้าหน้าที่ตรวจสอบ\"]','[\"ระบบสารสนเทศ\", \"บริการออนไลน์\", \"ล็อกอิน\", \"เข้าไม่ได้\", \"เบราว์เซอร์\"]','/uploads/00000000-0000-4000-8000-000000000016.png','[\"/uploads/00000000-0000-4000-8000-000000000016.png\"]','/uploads/00000000-0000-4000-8000-000000000016.pdf',NULL,164,'PUBLISHED',1,'2026-10-26 08:44:12.406000','2026-11-24 08:44:12.407000','2026-11-24 08:44:12.407000'),(17,5,'ขั้นตอนการตั้งและขอรีเซ็ตรหัสผ่านอย่างมั่นคงปลอดภัย','เกริ่นนำ\nรหัสผ่านเป็นปราการด่านแรกในการปกป้องข้อมูลส่วนบุคคลและข้อมูลราชการ หากลืมรหัสผ่านหรือสงสัยว่าบัญชีอาจถูกเข้าถึงโดยไม่ได้รับอนุญาต ควรดำเนินการรีเซ็ตรหัสผ่านผ่านช่องทางมาตรฐานและตั้งรหัสผ่านใหม่ตามหลักความมั่นคงปลอดภัยไซเบอร์\n\nเจ้าหน้าที่ศูนย์ ICT จะไม่มีนโยบายขอทราบรหัสผ่านปัจจุบันของผู้ใช้งานไม่ว่าทางโทรศัพท์ อีเมล หรือแชตส่วนตัว หากมีผู้แอบอ้างขอรหัสผ่าน โปรดปฏิเสธและแจ้งผู้ดูแลระบบทันที','[\"เปิดหน้าลงชื่อเข้าใช้ของระบบที่ต้องการ แล้วคลิกปุ่ม “ลืมรหัสผ่าน” (Forgot Password) เพื่อรับลิงก์หรือรหัสยืนยันผ่านช่องทางที่ลงทะเบียนไว้\", \"ตั้งรหัสผ่านใหม่ที่มีความยาวอย่างน้อย 12 ตัวอักษร โดยผสมตัวอักษรภาษาอังกฤษพิมพ์ใหญ่ พิมพ์เล็ก ตัวเลข และสัญลักษณ์พิเศษ\", \"หลีกเลี่ยงการใช้ข้อมูลที่คาดเดาง่าย เช่น วันเดือนปีเกิด เบอร์โทรศัพท์ ชื่อตัวเอง หรือตัวเลขเรียงกัน (123456)\", \"ไม่ใช้รหัสผ่านของระบบปฏิบัติงานราชการซ้ำกับรหัสผ่านของโซเชียลมีเดียหรือบริการส่วนตัว\", \"เปิดใช้งานการยืนยันตัวตนสองชั้น (Two-Factor Authentication: 2FA) ในทุกระบบที่รองรับเพื่อเพิ่มความปลอดภัยสูงสุด\"]','[\"รหัสผ่าน\", \"ลืมรหัสผ่าน\", \"บัญชีผู้ใช้\", \"ความปลอดภัย\", \"รีเซ็ตรหัสผ่าน\"]','/uploads/00000000-0000-4000-8000-000000000017.png','[\"/uploads/00000000-0000-4000-8000-000000000017.png\"]','/uploads/00000000-0000-4000-8000-000000000017.pdf',NULL,319,'PUBLISHED',1,'2026-11-20 08:44:12.457000','2026-11-24 08:44:12.458000','2026-11-24 08:44:12.458000'),(18,5,'วิธีสังเกตและป้องกันอีเมลหลอกลวง (Phishing) และไวรัสเรียกค่าไถ่ (Ransomware)','เกริ่นนำ\nภัยคุกคามทางไซเบอร์ในปัจจุบันมักมาในรูปแบบอีเมล ข้อความ SMS หรือลิงก์ปลอมที่แอบอ้างเป็นหน่วยงานราชการ ธนาคาร หรือผู้ให้บริการระบบคลาวด์ เพื่อหลอกให้ผู้ใช้งานกรอกรหัสผ่านหรือเปิดไฟล์แนบที่ฝังมัลแวร์เรียกค่าไถ่ (Ransomware) ซึ่งจะเข้ารหัสไฟล์งานทั้งหมดในเครื่อง\n\nการมีสติตรวจสอบผู้ส่งและลิงก์ปลายทางก่อนคลิกทุกครั้ง เป็นวิธีป้องกันที่มีประสิทธิภาพที่สุดและช่วยปกป้องทั้งข้อมูลของคุณและระบบเครือข่ายส่วนรวมของหน่วยงาน','[\"ตรวจสอบชื่อและที่อยู่อีเมลของผู้ส่งอย่างละเอียด (เช่น ระวังการสะกดโดเมนเลียนแบบ หรือใช้อีเมลฟรีแอบอ้างเป็นหน่วยงาน)\", \"สังเกตเนื้อหาที่ใช้ข้อความเร่งด่วนผิดปกติ เช่น ขู่ว่าจะระงับบัญชีภายใน 24 ชั่วโมง หรือแจ้งว่าได้รับรางวัล/ใบแจ้งหนี้ที่ไม่เคยทำรายการ\", \"นำเมาส์ไปวางชี้เหนือปุ่มหรือลิงก์ (โดยยังไม่ต้องคลิก) เพื่อดู URL ปลายทางที่แท้จริงที่มุมซ้ายล่างของหน้าจอ\", \"ห้ามเปิดไฟล์แนบที่เป็นไฟล์บีบอัดต้องสงสัย (.zip, .rar, .iso) หรือไฟล์เอกสารที่ขอให้กดเปิดใช้งานแมโคร (Enable Content / Macros)\", \"ตรวจสอบว่าโปรแกรมป้องกันไวรัส (Windows Security / Antivirus) และระบบปฏิบัติการได้รับการอัปเดตเป็นเวอร์ชันล่าสุดเสมอ\", \"หากเผลอคลิกลิงก์หรือเปิดไฟล์ต้องสงสัยแล้วเครื่องทำงานผิดปกติ ให้ถอดสาย LAN และปิด Wi-Fi ทันที แล้วรีบแจ้งเจ้าหน้าที่ศูนย์ ICT\"]','[\"ไวรัส\", \"สแกนไวรัส\", \"Phishing\", \"Ransomware\", \"อีเมล\", \"ความปลอดภัยไซเบอร์\", \"มัลแวร์\"]','/uploads/00000000-0000-4000-8000-000000000018.png','[\"/uploads/00000000-0000-4000-8000-000000000018.png\"]','/uploads/00000000-0000-4000-8000-000000000018.pdf',NULL,176,'PUBLISHED',0,'2026-10-14 08:44:12.513000','2026-11-24 08:44:12.514000','2026-11-24 08:44:12.514000');
