INSERT INTO `categories` VALUES (1,'คอมพิวเตอร์และอุปกรณ์','การใช้งาน บำรุงรักษา และแก้ไขปัญหาคอมพิวเตอร์ อุปกรณ์ต่อพ่วง และระบบปฏิบัติการเบื้องต้น','2026-11-24 08:44:09.229000'),(2,'ระบบเครือข่ายและอินเทอร์เน็ต','การเชื่อมต่อเครือข่ายไร้สาย (Wi-Fi) อินเทอร์เน็ต เครือข่ายภายใน และการตั้งค่า IP/DNS/VPN','2026-11-24 08:44:09.241000'),(3,'โปรแกรมและซอฟต์แวร์','คู่มือการใช้งานโปรแกรมสำนักงาน การประชุมออนไลน์ การจัดการไฟล์ และการสำรองข้อมูล','2026-11-24 08:44:09.246000'),(4,'เครื่องพิมพ์และอุปกรณ์ต่อพ่วง','การติดตั้งใช้งานเครื่องพิมพ์เครือข่าย เครื่องสแกนเนอร์ และอุปกรณ์ปฏิบัติการดิจิทัลของศูนย์ ICT','2026-11-24 08:44:09.253000'),(5,'ระบบสารสนเทศและบริการออนไลน์','การเข้าใช้บริการศูนย์พัฒนาทักษะและการเรียนรู้ ICT ขอนแก่น (kkict.net) ระบบสารสนเทศ และความมั่นคงปลอดภัยไซเบอร์','2026-11-24 08:44:09.258000');
